package com.bank.domain;

import java.util.*;
import java.util.logging.*;

public class DomainMappingDemo {
    private static final Logger log = Logger.getLogger("DomainMapping");

    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // The ALB has a DNS name and IPs that AWS may change over time.
        LoadBalancer alb = new LoadBalancer("my-alb-123456.ap-south-1.elb.amazonaws.com",
                List.of("13.235.10.42", "13.235.10.77"));
        DomainMapper mapper = new DomainMapper(alb);

        // Alias at the apex works and returns IPs directly (one step).
        log.info(() -> "Alias bank.example.com -> " + mapper.resolveAlias("bank.example.com", true));

        // CNAME on a subdomain works but needs a second lookup.
        log.info(() -> "CNAME www.bank.example.com -> " + mapper.resolveCname("www.bank.example.com", false));

        // CNAME at the apex is rejected by DNS rules.
        try {
            mapper.resolveCname("bank.example.com", true);
        } catch (ApexNotAllowedException e) {
            log.severe(() -> "CNAME at apex rejected: " + e.getMessage());
        }
    }
}

// ─── Would be in DomainMapper.java ───
class DomainMapper {
    private final LoadBalancer alb;
    DomainMapper(LoadBalancer alb) { this.alb = alb; }

    // Alias: Route 53 returns the resource's current IPs directly, apex allowed, free.
    String resolveAlias(String name, boolean isApex) {
        return "A records " + alb.currentIps() + " (one step, apex=" + isApex + ", tracks ALB IPs)";
    }

    // CNAME: returns a name; a second lookup is needed; apex is forbidden.
    String resolveCname(String name, boolean isApex) {
        if (isApex) {
            throw new ApexNotAllowedException("CNAME not allowed at zone apex " + name);
        }
        return alb.dnsName() + " (then resolve that name -> IPs: second lookup)";
    }
}

// ─── Would be in LoadBalancer.java ───
class LoadBalancer {
    private final String dnsName;
    private final List<String> currentIps;
    LoadBalancer(String dnsName, List<String> currentIps) {
        this.dnsName = dnsName; this.currentIps = currentIps;
    }
    String dnsName() { return dnsName; }
    List<String> currentIps() { return currentIps; }
}

// ─── Would be in ApexNotAllowedException.java ───
class ApexNotAllowedException extends RuntimeException {
    ApexNotAllowedException(String message) { super(message); }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                r.getMillis(), r.getLevel(), r.getMessage());
    }
}
